description:
Implement a one-bit wide, 4-to-1 multiplexer. The module takes four input data lines (D[0] to D[3]) and uses a 2-bit select signal (S) to choose which input to route to the output (Y). Depending on the value of S, Y will reflect the value of one of the four inputs: when S is 00, Y outputs D[0]; when S is 01, Y outputs D[1]; when S is 10, Y outputs D[2]; and when S is 11, Y outputs D[3].
module top_module(
	input  [3:0] D,
	input  [1:0] S,
	output reg Y
);

code:
module top_module(
	input  [3:0] D,
	input  [1:0] S,
	output reg Y
);always @(*) begin
		case (S)
			2'b00: Y = D[0];
			2'b01: Y = D[1];
			2'b10: Y = D[2];
			2'b11: Y = D[3];
		endcase
	end

endmodule

