module top_module(
	input clk,	
	input ym_so,
	input ym_sh1,
	input ym_sh2,
	input ym_p1,
	output reg [15:0] left,
	output reg [15:0] right,
	output reg [15:0] left_exp,
	output reg [15:0] right_exp,	
	output            update_left,
	output            update_right
);reg [12:0] sreg;
reg last_ym_sh1,last_ym_sh2;

reg [15:0] dr,dl;
reg [15:0] left0_pm, right0_pm;
reg [ 2:0] sr,sl;

reg [15:0] out_r,out_l;
reg update_l, update_r;

always @(posedge ym_p1) begin : sh_edges
	last_ym_sh1 <= ym_sh1;
	last_ym_sh2 <= ym_sh2;
end

always @(posedge ym_p1) begin : shift_register

	sreg <= {ym_so,sreg[12:1]};

	if(last_ym_sh1 & ~ym_sh1)
	begin
		update_r <= 1'b1;
		out_r    <= dr;
		sr       <= sreg[12:10];
		dr       <= {~sreg[9],sreg[8:0],6'b000000};
		right0_pm<= { 3'd0, sreg };
	end else begin
		update_r <= 1'b0;
		if(sr<7) begin
			sr       <= sr + 1;
			dr[14:0] <= dr[15:1];
		end
	end

	if(last_ym_sh2 & ~ym_sh2)
	begin
		update_l <= 1'b1;
		out_l    <= dl;		
		sl       <= sreg[12:10];
		dl       <= {~sreg[9],sreg[8:0],6'b000000};
		left0_pm <= { 3'd0, sreg };
	end else begin
		update_l <= 1'b0;
		if(sl<7) begin
			sl       <= sl + 1;
			dl[14:0] <= dl[15:1];
		end
	end
end

reg [1:0] aux_upr, aux_upl;
assign update_right = aux_upr[1];
assign update_left  = aux_upl[1];

always @(posedge clk) begin : update_sync
	aux_upr[0] <= update_r;
	aux_upr[1] <= aux_upr[0];
	aux_upl[0] <= update_l;
	aux_upl[1] <= aux_upl[0];
end

reg [15:0] aux_l, aux_r, left1, right1;

always @(posedge clk) begin : output_sync
	if( update_l | update_r ) begin
		aux_r    <= out_r;
		right    <= aux_r;
		aux_l    <= out_l;
		left     <= aux_l;

		left1    <= left0_pm;
		left_exp <= left1;
		right1   <= right0_pm;
		right_exp<= right1;
	end
end

endmodule

