            ym_p1 = 0;
            ym_sh1 = 0;
            ym_sh2 = 0;
            ym_so = 0;
            repeat(2) @(posedge clk);
        end
        endtask
    task shift_data;

        input [15:0] data;
        input integer channel;
        integer i;
        begin
            @(posedge clk);
            if (channel == 1) ym_sh1 = 1; else ym_sh2 = 1;

            for (i = 15; i >= 0; i = i - 1) begin
                ym_so = data[i];
                @(posedge clk);
            end

            ym_sh1 = 0;
            ym_sh2 = 0;
            ym_so = 0;


            ym_p1 = 1;
            @(posedge clk);
