    wire xor_logical = !(a & b) && (a | b);

    // Generate the output based on the select input
    assign out_xor_bitwise = select ? xor_bitwise : 4'b0;
    assign out_xor_logical = select ? xor_logical : 1'b0;
    assign out_not = select ? {b_inv, a_inv} : 8'b0;

endmodule

