   always @(posedge writeClk)
     begin
        if (writeEnable!=0)
          begin
             if(writeMask==1)
               begin
                  mem[writeAddress] <= writeData;
               end
             else
               begin
                  for(i=0; i<writeMask; i=i+1)
                    if(writeEnable[i]==1)
                      mem[writeAddress][i] <= writeData[i];
               end
          end
     end

   always @(posedge readClk)
     begin
        if(readEnable)
          begin
             readData <= mem[readAddress];
          end
     end

endmodule

