description:
Design a forwarding unit for a pipelined processor to manage data hazards. The circuit takes in the destination registers of the decode stage (de_Rs, de_Rt) and the write registers from the execute (em_write_reg) and memory (mw_write_reg) stages, along with control signals indicating whether those registers will be written (em_reg_wr, mw_reg_wr). It generates two output selectors (frwrd_sel_A and frwrd_sel_B) to determine whether to forward data from the execute stage or memory stage for the operands associated with de_Rs and de_Rt. This prevents incorrect data usage resulting from pipeline stalls by allowing the use of up-to-date values in subsequent instruction processing.
module top_module(de_Rs, de_Rt, em_write_reg, mw_write_reg, em_reg_wr, mw_reg_wr,
  frwrd_sel_A, frwrd_sel_B);

code:
module top_module(de_Rs, de_Rt, em_write_reg, mw_write_reg, em_reg_wr, mw_reg_wr,
  frwrd_sel_A, frwrd_sel_B);input em_reg_wr, mw_reg_wr; 
  input [2:0] de_Rs, de_Rt; 
  input [2:0] em_write_reg, mw_write_reg; 
  output [1:0] frwrd_sel_A, frwrd_sel_B; 

  assign frwrd_sel_A = (de_Rs == em_write_reg & em_reg_wr) ? 2'b01 : 
                       (de_Rs == mw_write_reg & mw_reg_wr) ? 2'b10 : 
                       2'b00; 

  assign frwrd_sel_B = (de_Rt == em_write_reg & em_reg_wr) ? 2'b01 : 
                       (de_Rt == mw_write_reg & mw_reg_wr) ? 2'b10 : 
                       2'b00; 

endmodule

