module binary_counter_8 
(
  input rst,
  input clk,
  input en,

  output reg [7:0] count
);

  always @(posedge clk or posedge rst) begin
    if (rst) 
	begin
      count <= 8'b00000000;
    end 
	else if (en) 
	begin
      count <= count + 1;
    end
  end

endmodule

