module top_module(
    input clk,            // Added clock input
    input reset,         // Added reset input
    input [7:0] D,
    output reg P
);reg [3:0] count;
reg [1:0] stage;

always @(*) begin
    case (stage)
        2'b00: count = D[3:0] + D[7:4];      // Changed count[3:0] to count 
        2'b01: count = count[1:0] + count[3:2]; // Changed count[3:0] to count 
        2'b10: count = count[2:0] + count[3]; // Changed count[3:0] to count 
        2'b11: P = ~count[0];
        default: count = 4'b0000;           // Default case to avoid latches
    endcase
end

always @(posedge clk or posedge reset) begin  // Added reset sensitivity
    if (reset) begin
        count <= 4'b0;
        stage <= 2'b00;
        P <= 1'b0;
    end else begin
        case (stage)
            2'b00: stage <= 2'b01;
            2'b01: stage <= 2'b10;
            2'b10: stage <= 2'b11;
            2'b11: stage <= 2'b00;
        endcase
    end
end

endmodule

